public class Solution {
  /**
   * 单调递减队列（存下标）：
   *  1) 队首滑出窗口就弹；
   *  2) 队尾所有 <= 新值的元素永不可能是窗口最大值，弹掉；
   *  3) 窗口形成后累加队首。
   * 每个下标进出队各至多一次 → 摊还 O(n)。求和在 long 域，避免 2e5 * 2e9 溢出。
   */
  public static long slidingWindowMaxTotal(int[] loads, int windowSize) {
    if (loads == null || windowSize <= 0 || windowSize > loads.length) return -1;
    int n = loads.length;
    int[] deque = new int[n];
    int head = 0;
    int tail = 0;                 // 半开区间 [head, tail)
    long total = 0L;
    for (int r = 0; r < n; r++) {
      if (head < tail && deque[head] <= r - windowSize) head++;      // 队首滑出窗口
      while (head < tail && loads[deque[tail - 1]] <= loads[r]) tail--;  // 队尾支配弹除
      deque[tail++] = r;
      if (r >= windowSize - 1) total += loads[deque[head]];          // 完整窗口的最大值
    }
    return total;
  }
}

runner.naiveSolution:
public class Solution {
  // 朴素：拿"全局最大值 × 窗口个数"当峰值合计。只有当所有窗口都恰好包含全局最大值时才对，
  // 局部峰值被完全忽略 —— 这正是容量评审最危险的乐观估计。
  public static long slidingWindowMaxTotal(int[] loads, int windowSize) {
    if (loads == null || windowSize <= 0 || windowSize > loads.length) return -1;
    int global = loads[0];
    for (int v : loads) if (v > global) global = v;
    return (long) global * (loads.length - windowSize + 1);
  }
}
